      type: typeKey,
      mesh,
      x, y: 0, z, yaw,
      vx: 0, vz: 0,
      angularVel: 0,
      steer: 0,
      speed: 0,
      forwardSpeed: 0,
      lateralSpeed: 0,
      wheelSpin: 0,
      health: 100,
      driver: opts.driver || null,     // 'player' | 'traffic' | 'police'
      ai: opts.ai || null,
      police: typeKey === 'police',
      isPlayer: false,
